#!/bin/bash
# =============================================================================
# Deterministic prep of SIFT1B attribute builder inputs.
#
# Produces, under $OUT (default /mnt/nvme/.../datasets/sift1b/sift1b_build):
#   sift1b_tags5.u32       [N,5] uint32 = [org,dept,team,project | price]
#   sift1b_group_tags.txt  org column, one int/line (PerTagBKT routing key)
#
# Upstream tags are generated by:
#   SIFT1B_ROOT=$DS python3 Tools/benchmarks/gen_sift1b_attrs.py
# =============================================================================
set -e
cd "$(dirname "$0")/../.."
ROOT=$(pwd)
SB="$ROOT/Release/spannbuilder"

DS=${SIFT1B_ROOT:-/mnt/nvme/baotonglu/mocheng/datasets/sift1b}
TAGS=$DS/multitenant/tags.npy
NUM=$DS/multitenant/num_attr.npy
OUT=${SIFT1B_BUILD_OUT:-$DS/sift1b_build}
N="${1:--1}"

mkdir -p "$OUT"
echo "[prep-sift1b] DS=$DS OUT=$OUT N=$N"

"$SB" --merge-tags5 \
  --tags-npy "$TAGS" --num-npy "$NUM" \
  --out-tags5 "$OUT/sift1b_tags5.u32" --out-group "$OUT/sift1b_group_tags.txt" \
  --acl-cols 4 --group-col 0 --n "$N"

echo "[prep-sift1b] done."
